proposals.new_text:
- name: Run funnel hack digest
        run: node scripts/funnel-hack-digest.js
        retry-on-error: true
        retry-max-attempts: 2
        retry-delay-seconds: 60

      - name: Notify on failure
        if: failure()
        uses: actions/github-script@v7
        with:
          script: |
            const msg = `Funnel-Hack Digest failed on ${new Date().toISOString()}. Check the run log: ${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
            await fetch(process.env.SLACK_WEBHOOK_URL, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ text: msg })
            });
        env:
          SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK_URL }}
